var viewNow = time.Date(2026, 10, 10, 12, 0, 0, 0, time.UTC)

// maxViewLines bounds each list a view carries, so 20 regions' views stay
// small in one dashboard fan-out.
const maxViewLines = 16

// View is one region's cost as its summary carries it.
type View struct {
	Cell      string `json:"cell"`
	OCIRegion string `json:"oci_region,omitempty"`
	// Missing says why the region has no report yet; Forecast and the
	// lines are then empty.
	Missing    string   `json:"missing,omitempty"`
	Forecast   Forecast `json:"forecast"`
	Services   []Line   `json:"services,omitempty"`
	Components []Line   `json:"components,omitempty"`
	// UntaggedCents is this month's cost without a component tag.
	UntaggedCents uint64 `json:"untagged_cents"`
}

// Summarize is the view of report at now: its forecast with the region's
// autoscaled hosts.
func Summarize(report Report, now time.Time, hosts []Host) View {
	forecast := Project(report, now, hosts)
	var tagged uint64
	for _, line := range report.Components {
		tagged += line.Cents
	}
	return View{Cell: report.Cell, OCIRegion: report.OCIRegion, Forecast: forecast,
		Services:      fold(report.Services),
		Components:    fold(report.Components),
		UntaggedCents: subtractFloor(forecast.MonthToDateCents, tagged)}
}

// fold keeps the costliest lines and merges the rest into one Other line.
func fold(lines []Line) []Line {
	if len(lines) <= maxViewLines {
		return slices.Clone(lines)
	}
	out := slices.Clone(lines[:maxViewLines-1])
	other := Line{Name: "Other"}
	for _, line := range lines[maxViewLines-1:] {
		other.Cents += line.Cents
	}
	return append(out, other)
}

func subtractFloor(a, b uint64) uint64 {
	if b > a {
		return 0
	}
	return a - b
}

func Project(report Report, now time.Time, hosts []Host) Forecast {
	monthStart, monthEnd := monthBounds(now)
	nextEnd := monthEnd.AddDate(0, 1, 0)
	through := report.Through
	forecast := Forecast{Currency: report.Currency, ObservedAt: report.ObservedAt, Through: through}

	for _, entry := range report.Days {
		inMonth := !entry.Day.Before(monthStart)
		if inMonth && entry.Day.Before(monthEnd) {
			forecast.MonthToDateCents += entry.Cents
		}
		if inMonth && entry.Day.Before(through) {
			forecast.CompleteCents += entry.Cents
		}
	}

	// A new region averages only the days it has, so its rate is not diluted
	// by days before it existed.
	from := through.Add(-RateDays * day)
	if len(report.Days) > 0 && report.Days[0].Day.After(from) {
		from = report.Days[0].Day
	}
	if from.After(through) {
		from = through
	}
	n := int(through.Sub(from) / day)
	var window uint64
	for _, entry := range report.Days {
		if !entry.Day.Before(from) && entry.Day.Before(through) {
			window += entry.Cents
		}
	}
	forecast.RateFrom = from
	forecast.AveragedDays = n
	if n > 0 {
		forecast.RateCents = ceilDiv(window, uint64(n))
	}

	var pending uint64
	for _, host := range hosts {
		daily := ceilDiv(host.MonthlyCents*12, 365)
		if n == 0 {
			pending += daily
			continue
		}
		var covered int
		switch {
		case !host.Created.IsZero() && !host.Created.After(from):
			covered = n
		case host.Created.IsZero() || !host.Created.Before(through):
			covered = 0
		default:
			covered = min(n, int(through.Sub(host.Created)/day))
		}
		missed := n - covered
		pending += ceilDiv(daily*uint64(missed), uint64(n))
	}
	forecast.PendingDailyCents = pending

	start := through
	if start.Before(monthStart) {
		start = monthStart
	}
	forecast.DaysLeft = int(monthEnd.Sub(start) / day)
	perDay := forecast.RateCents + pending
	forecast.MonthEndCents = forecast.CompleteCents + perDay*uint64(forecast.DaysLeft)
	forecast.NextMonthCents = perDay * uint64(nextEnd.Sub(monthEnd)/day)
	return forecast
}

// ceilDiv rounds up, so every division in a projection errs high.
func ceilDiv(a, b uint64) uint64 {
	return (a + b - 1) / b
}

// jsonFloat retains the lexical distinction between a JSON integer and a JSON
// floating point amount. OCI billed GiB and receipt byte counts require integers.
type jsonFloat float64

func decodeJSON(wire []byte) (any, error) {
	decoder := jsontext.NewDecoder(bytes.NewReader(wire))
	value, err := decodeValue(decoder)
	if err != nil {
		return nil, err
	}
	if _, err = decoder.ReadToken(); err != io.EOF {
		if err == nil {
			err = fmt.Errorf("extra JSON value")
		}
		return nil, err
	}
	return value, nil
}
func decodeValue(decoder *jsontext.Decoder) (any, error) {
	token, err := decoder.ReadToken()
	if err != nil {
		return nil, err
	}
	switch token.Kind() {
	case 'n':
		return nil, nil
	case 't':
		return true, nil
	case 'f':
		return false, nil
	case '"':
		return token.String(), nil
	case '0':
		s := token.String()
		if strings.ContainsAny(s, ".eE") {
			f, err := strconv.ParseFloat(s, 64)
			return jsonFloat(f), err
		}
		return strconv.ParseInt(s, 10, 64)
	case '{':
		m := Object{}
		for decoder.PeekKind() != '}' {
			key, err := decoder.ReadToken()
			if err != nil {
				return nil, err
			}
			if key.Kind() != '"' {
				return nil, fmt.Errorf("JSON object requires a field name")
			}
			name := key.String()
			if _, ok := m[name]; ok {
				return nil, fmt.Errorf("duplicate JSON field")
			}
			value, err := decodeValue(decoder)
			if err != nil {
				return nil, err
			}
			m[name] = value
		}
		_, err := decoder.ReadToken()
		return m, err
	case '[':
		a := []any{}
		for decoder.PeekKind() != ']' {
			value, err := decodeValue(decoder)
			if err != nil {
				return nil, err
			}
			a = append(a, value)
		}
		_, err := decoder.ReadToken()
		return a, err
	}
	return nil, fmt.Errorf("invalid JSON token")
}

func integer(v any) bool {
	switch x := v.(type) {
	case int, int64:
		return true
	case float64:
		return !math.IsNaN(x) && !math.IsInf(x, 0) && math.Trunc(x) == x
	}
	return false
}
func number(v any) float64 {
	if _, ok := v.(bool); ok {
		fail("boolean is not a number")
	}
	f, err := strconv.ParseFloat(str(v), 64)
	if err != nil || math.IsNaN(f) || math.IsInf(f, 0) {
		fail("invalid numeric amount")
	}
	return f
}
func rat(v any) *big.Rat {
	if _, ok := v.(bool); ok {
		fail("boolean is not a number")
	}
	if r, ok := v.(*big.Rat); ok {
		return new(big.Rat).Set(r)
	}
	r, ok := new(big.Rat).SetString(str(v))
	if !ok {
		fail("invalid numeric amount")
	}
	return r
}

func positiveGiB(v any, label string) any {
	if !integer(v) || number(v) <= 0 {
		fail(label + " must be a positive integer billed GiB amount")
	}
	return v
}

func fixed(v any, n int) string {
	r := rat(v)
	scale := new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(n)), nil)
	num := new(big.Int).Mul(r.Num(), scale)
	q, rem := new(big.Int), new(big.Int)
	q.QuoRem(num, r.Denom(), rem)
	twice := new(big.Int).Mul(new(big.Int).Abs(rem), big.NewInt(2))
	cmp := twice.Cmp(r.Denom())
	if cmp > 0 || (cmp == 0 && q.Bit(0) == 1) {
		if r.Sign() < 0 {
			q.Sub(q, big.NewInt(1))
		} else {
			q.Add(q, big.NewInt(1))
		}
	}
	negative := q.Sign() < 0
	s := new(big.Int).Abs(q).String()
	for len(s) <= n {
		s = "0" + s
	}
	if n > 0 {
		s = s[:len(s)-n] + "." + s[len(s)-n:]
	}
	if negative {
		s = "-" + s
	}
	return s
}

func privateAddr(a netip.Addr) bool {
	private := []string{"0.0.0.0/8", "10.0.0.0/8", "127.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12", "192.0.0.0/24", "192.0.0.170/31", "192.0.2.0/24", "192.168.0.0/16", "198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "255.255.255.255/32"}
	if a == netip.MustParseAddr("192.0.0.9") || a == netip.MustParseAddr("192.0.0.10") {
		return false
	}
	for _, cidr := range private {
		if netip.MustParsePrefix(cidr).Contains(a) {
			return true
		}
	}
	return false
}
func privatePrefix(p netip.Prefix) bool {
	// Inventory plans accept non-global IPv4 space; private peer intents require
	// RFC1918. Check both boundary addresses, as in the original contract.
	if !p.IsValid() || !p.Addr().Is4() || p != p.Masked() {
		return false
	}
	last := p.Addr().As4()
	for bit := p.Bits(); bit < 32; bit++ {
		last[bit/8] |= 1 << uint(7-bit%8)
	}
	return privateAddr(p.Addr()) && privateAddr(netip.AddrFrom4(last))
}

func readBytes(path string, limit int, label string) []byte {
	fd, err := unix.Open(path, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
	if err != nil {
		fail(label + " is unreadable or invalid JSON")
	}
	f := os.NewFile(uintptr(fd), path)
	defer f.Close()
	st, err := f.Stat()
	if err != nil {
		fail(label + " is unreadable or invalid JSON")
	}
	if !st.Mode().IsRegular() || st.Size() <= 0 || st.Size() > int64(limit) {
		fail(label + " has invalid size or is not a regular file")
	}
	wire := must(io.ReadAll(io.LimitReader(f, int64(limit+1))))
	if len(wire) == 0 || len(wire) > limit {
		fail(label + " has invalid size")
	}
	return wire
}
func readJSON(path string, limit int, label string) Object {
	wire := readBytes(path, limit, label)
	v, err := decodeJSON(wire)
	if err != nil {
		if strings.Contains(err.Error(), "duplicate") {
			fail("JSON document has duplicate fields")
		}
		fail(label + " is unreadable or invalid JSON")
	}
	m, ok := v.(map[string]any)
	if !ok {
		fail(label + " must be an object")
	}
	return m
}

func capture[T any](fn func() T) (v T, err error) {
	defer func() {
		if r := recover(); r != nil {
			if e, ok := r.(error); ok {
				err = e
			} else {
				err = fmt.Errorf("%v", r)
			}
		}
	}()
	return fn(), nil
}
func ReadJSON(path string, limit int, label string) (Object, error) {
	return capture(func() Object { return readJSON(path, limit, label) })
}

func (e *Engine) Invoke(name string, args []any, kwargs Object) (any, error) {
	return capture(func() any { return e.invoke(name, args, kwargs) })
}
func (e *Engine) invoke(name string, args []any, kw Object) any {
	arg := func(i int) any {
		if i < len(args) {
			return args[i]
		}
		return nil
	}
	option := func(i int, key string, fallback any) any {
		if i < len(args) {
			return args[i]
		}
		if v, ok := kw[key]; ok {
			return v
		}
		return fallback
	}
	now := e.now()
	if t, ok := option(3, "now", nil).(time.Time); ok {
		now = t
	}
	switch name {
	case "main":
		e.run(e.Argv[1:])
		return nil
	case "load_plan":
		path := pathValue(option(0, "path", Path(e.PlanPath)))
		return e.loadPlan(path)
	case "require_ocid":
		return requireOCID(arg(0), str(arg(1)), text(option(2, "region", "")))
	case "oci":
		return e.realOCI(args, kw)
	case "checked_tool":
		return e.realChecked(args)

func (e *Engine) realOCI(args []any, kwargs Object) any {
	words := make([]string, len(args))
	for i, x := range args {
		words[i] = str(x)
	}
	region := text(kwargs["region"])
	client, err := sdkcli.ForRegion(region)
	if err != nil {
		fail(fmt.Sprintf("OCI read cannot be served in-binary for region %q: %v", region, err))
	}
	ctx, cancel := context.WithTimeout(e.ctx(), ociReadTimeout)
	defer cancel()
	data, _, err := client.Call(ctx, words)
	if err != nil {
		if ctxErr := ctx.Err(); ctxErr != nil {
			panic(ctxErr)
		}
		fail(err.Error())
	}
	v, err := decodeJSON(data)
	if err != nil {
		fail("invalid OCI response for " + strings.Join(words[:min(3, len(words))], " "))
	}
	return v

func (e *Engine) call(name string, args []any, kwargs Object) any {
	if e.Dependency != nil && (name == "oci" || name == "checked_tool" || name == "subprocess.run" || name == "cloudflare_origin_ips" || e.Overrides[name]) {
		v, err := e.Dependency(name, args, kwargs)
		if err != nil {
			panic(err)
		}
		return v
	}
	return e.invoke(name, args, kwargs)
}
func (e *Engine) oci(region string, args ...string) any {
	a := make([]any, len(args))
	for i, x := range args {
		a[i] = x
	}
	kw := Object{}
	if region != "" {
		kw["region"] = region
	}
	return e.call("oci", a, kw)
}
func (e *Engine) process(command []string) Object {
	args := []any{arr(command)}
	kw := Object{"capture_output": true, "text": true, "timeout": 180, "check": false}
	if e.Dependency != nil {
		return obj(e.call("subprocess.run", args, kw))
	}

var (
	clientsMu sync.Mutex
	clients   = map[string]*Client{}
)

// ForRegion returns the shared client for region. An empty region selects
// the bootstrap region, which serves the tenancy-global IAM reads the CLI
// sent to the profile's default region.
func ForRegion(region string) (*Client, error) {
	if region == "" {
		region = catalog.OCIRegion(catalog.Bootstrap)
	}
	clientsMu.Lock()
	defer clientsMu.Unlock()
	if client := clients[region]; client != nil {
		return client, nil
	}
	factory, err := ociclient.OperatorConfig(region)
	if err != nil {
		return nil, err
	}
	client := NewClient(factory, "")
	clients[region] = client
	return client, nil
}

// Call serves one CLI command and returns the CLI "data" document as JSON.
// handled is false, with ErrUnsupported, when the command is not served.
func (c *Client) Call(ctx context.Context, args []string) (data jsontext.Value, handled bool, err error) {
	command, err := Parse(args)
	if err != nil {
		return nil, false, err
	}
	if _, ok := command.Flags["output"]; ok {
		return nil, false, errors.New("OCI --output is fixed to json")
	}
	if _, ok := command.Flags["region"]; ok {
		return nil, false, errors.New("OCI --region is selected by the caller")
	}
	handler, ok := handlers[command.Path]
	if !ok {
		return nil, false, fmt.Errorf("%w: %s", ErrUnsupported, command.Path)
	}
	value, err := handler(ociclient.RequestContext(ctx), c, command)
	if err != nil {
		return nil, true, fmt.Errorf("OCI read failed: %s: %w", command.Path, err)
	}
	if unused := command.unused(); len(unused) > 0 {
		// The read ignored a flag, so its result may be wider than asked
		// for. Report the command as unsupported rather than answer it.
		return nil, false, fmt.Errorf("%w: %s with --%s", ErrUnsupported, command.Path, strings.Join(unused, ", --"))
	}
	data, err = Render(value)
	return data, true, err
}

func Parse(args []string) (Command, error) {
	command := Command{Flags: map[string]string{}, used: map[string]bool{}}
	var path []string
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if !strings.HasPrefix(arg, "--") {
			if len(command.Flags) > 0 || command.All {
				return Command{}, fmt.Errorf("positional OCI argument %q follows a flag", arg)
			}
			path = append(path, arg)
			continue
		}
		name := strings.TrimPrefix(arg, "--")
		if name == "all" {
			command.All = true
			continue
		}
		if i+1 >= len(args) || strings.HasPrefix(args[i+1], "--") {
			return Command{}, fmt.Errorf("OCI flag --%s has no value", name)
		}
		if _, repeated := command.Flags[name]; repeated {
			return Command{}, fmt.Errorf("OCI flag --%s is repeated", name)
		}
		command.Flags[name] = args[i+1]
		i++
	}
	command.Path = strings.Join(path, " ")
	return command, nil
}

// value returns a flag's value, or "", and records that it was read.
func (c Command) value(name string) string {
	if c.used != nil {
		c.used[name] = true
	}
	return c.Flags[name]
}

// unused lists the flags no handler read, in sorted order.
func (c Command) unused() []string {
	var names []string
	for name := range c.Flags {
		if !c.used[name] {
			names = append(names, name)
		}
	}
	slices.Sort(names)
	return names
}

func (c Command) flag(name string) (string, error) {
	value := c.value(name)
	if value == "" {
		return "", fmt.Errorf("OCI %s requires --%s", c.Path, name)
	}
	return value, nil

func bucketFlags(command Command) (string, string, error) {
	namespace, err := command.flag("namespace-name")
	if err != nil {
		return "", "", err
	}
	bucket, err := command.flag("bucket-name")
	return namespace, bucket, err
}

func osObjectList(ctx context.Context, c *Client, command Command) (any, error) {
	namespace, bucket, err := bucketFlags(command)
	if err != nil {
		return nil, err
	}
	client, err := c.objects()
	if err != nil {
		return nil, err
	}
	return pages(command.All, func(start *string) ([]objectstorage.ObjectSummary, *string, error) {
		response, err := client.ListObjects(ctx, objectstorage.ListObjectsRequest{NamespaceName: &namespace,
			BucketName: &bucket, Fields: command.optional("fields"), Start: start})
		if err == nil && response.Objects == nil {
			return nil, nil, fmt.Errorf("OCI object list lacks objects")
		}
		return response.Objects, response.NextStartWith, err
	})

